                              rosterParent.get(draggedBotId) === parentId
                            ) {
                              event.preventDefault();
                              event.dataTransfer.dropEffect = "move";
                            }
                          }}
                          onDrop={(event) => {
                            if (
                              item.kind !== "bot" ||
                              !draggedBotId ||
                              rosterParent.get(draggedBotId) !== parentId
                            )
                              return;
                            event.preventDefault();
                            reorderRosterBot(draggedBotId, item.chat.id, groupBotIds);
                            setDraggedBotId(null);
                          }}
                          onDragEnd={() => setDraggedBotId(null)}
                          onKeyDown={(event) => {
