// Usage: node add-headers.mjs <web/src dir>
// Prepends the rakazo attribution header to copied files that lack it.
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = process.argv[2];
const MARK = "rakazo@912c977";
const TS = "// Modified from rakazo (Apache-2.0), github.com/elie222/rakazo@912c977";
const CSS = "/* Modified from rakazo (Apache-2.0), github.com/elie222/rakazo@912c977 */";
const files = [
  ...["alert-dialog", "button", "dialog", "dropdown-menu", "input-group", "input", "popover", "separator", "skeleton", "spinner", "textarea", "tooltip"].map((n) => `components/ui/${n}.tsx`),
  "components/avatar/bot-avatar.tsx", "components/avatar/group-avatar.tsx", "components/avatar/avatar-style.tsx",
  "lib/avatar/avatar-motion.ts", "lib/avatar/avatar-shape.ts", "lib/avatar/bot-avatar-colors.ts", "lib/avatar/bot-avatar-shapes.ts",
  "components/markdown/markdown.web.tsx", "components/markdown/markdown.ts", "components/markdown/markdown-table.tsx",
  "components/markdown/table-utils.ts", "components/markdown/icons.tsx", "components/markdown/markdown-link-prompt.tsx",
  "components/markdown/markdown-text.ts", "components/markdown/linkify-it.d.ts",
  "lib/utils.ts", "lib/tokens.ts", "lib/appearance.ts", "lib/transcript-scroll.ts",
  "styles.css", "styles/tokens.css", "styles/ui.css", "styles/shadcn.css", "styles/markdown.web.css", "styles/markdown-table.css",
];
for (const rel of files) {
  const path = join(root, rel);
  const src = readFileSync(path, "utf8");
  if (src.includes(MARK)) continue;
  let out;
  if (rel.endsWith(".css")) out = `${CSS}\n${src}`;
  else {
    const m = src.match(/^(["']use client["'];?\n)/);
    out = m ? `${m[1]}${TS}\n${src.slice(m[1].length)}` : `${TS}\n${src}`;
  }
  writeFileSync(path, out);
  console.log("header:", rel);
}

