/* Chrome is not table text: row numbers, the toolbar strip, the pager range,
   and the empty state must stay out of text selections so a dragged excerpt
   still matches the message's rendered text for quoting. */
.rk-table-head,
.rk-table-gutter,
.rk-table-footer,
.rk-table-empty {
  user-select: none;
}

.rk-table-scroll {
  overflow: auto;
  max-height: 20em;
}

.rk-table td {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 0.92em;
  color: var(--foreground);
}

.rk-table thead th {
  position: sticky;
  position: static;
  padding: 0.3em 0.45em;
  border: 0;
  border-bottom: 1px solid var(--border);
  border-radius: 0;
  background: transparent;
}

.rk-table-card > .rk-table-head .rk-table-tool {
  opacity: 0;
}

.rk-table-dialog .rk-table-head {
  padding: 0.45em 0.7em;
  border-bottom: 1px solid var(--border);
}

.rk-table-box .rk-table {
  display: table;
  width: max-content;
  min-width: 100%;
  /* Cancel the legacy .rk-chat-markdown table clamp so wide tables overflow
     into .rk-table-scroll instead of scrolling the <table> element itself. */
  max-width: none;
  overflow: visible;
  margin: 0;
  border-collapse: collapse;
  font-size: 0.85em;
}

.rk-table-box .rk-table th,
.rk-table-box .rk-table td {
  border: 0;
  border-bottom: 1px solid var(--border);
  padding: 0.35em 0.75em;
  white-space: nowrap;
  overflow-wrap: normal;
}

.rk-table-card:hover > .rk-table-head .rk-table-tool,
.rk-table-card:focus-within > .rk-table-head .rk-table-tool {
  opacity: 1;
}

@media (hover: none), (pointer: coarse) {
  .rk-table-tool {
    width: 44px;
    height: 44px;
  }

  button.rk-table-sort,
  .rk-table-sort-trigger {
    min-width: 44px;
    min-height: 44px;
  }

  .rk-table-card > .rk-table-head .rk-table-tool {
    opacity: 1;
  }
}

