// Usage: node cdp-check.mjs <baseUrl> <outDir>
// Drives headless Chromium over CDP: mobile overlay, send flow, overflow checks, screenshots.
import { spawn } from "node:child_process";
import { writeFileSync } from "node:fs";

const [base, outDir] = process.argv.slice(2);
const shell =
  "/Users/apple/Library/Caches/ms-playwright/chromium_headless_shell-1228/chrome-headless-shell-mac-arm64/chrome-headless-shell";
const port = 9333;
const chrome = spawn(shell, [
  `--remote-debugging-port=${port}`,
  "--user-data-dir=/Users/apple/.claude/jobs/1ad8a391/tmp/chrome-profile-cdp",
  "--hide-scrollbars",
  "about:blank",
]);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function target() {
  for (let i = 0; i < 50; i++) {
    try {
      const list = await (await fetch(`http://127.0.0.1:${port}/json`)).json();
      const page = list.find((t) => t.type === "page");
      if (page) return page.webSocketDebuggerUrl;
    } catch {}
    await sleep(200);
  }
  throw new Error("no CDP target");
}

const ws = new WebSocket(await target());
await new Promise((r) => ws.addEventListener("open", r));
let seq = 0;
const pending = new Map();
ws.addEventListener("message", (event) => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg);
    pending.delete(msg.id);
  }
});
const send = (method, params = {}) =>
  new Promise((resolve) => {
    const id = ++seq;
    pending.set(id, resolve);
    ws.send(JSON.stringify({ id, method, params }));
  });
const evaluate = async (expression) =>
  (await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true })).result?.result?.value;
const shot = async (name) => {
  const { result } = await send("Page.captureScreenshot", { format: "png" });
  writeFileSync(`${outDir}/${name}.png`, Buffer.from(result.data, "base64"));
  console.log("shot", name);
};
const viewport = (width, height, mobile) =>
  send("Emulation.setDeviceMetricsOverride", { width, height, deviceScaleFactor: 1, mobile });
const go = async (url) => {
  await send("Page.navigate", { url });
  await sleep(2500);
};
const overflow = () =>
  evaluate(
    "JSON.stringify({scrollW: document.documentElement.scrollWidth, innerW: innerWidth, bodyScrollW: document.body.scrollWidth})",
  );
const typeAndSend = (text) =>
  evaluate(`(() => {
    const ta = document.querySelector('textarea[name="chat-message"]');
    const setter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set;
    setter.call(ta, ${JSON.stringify(text)});
    ta.dispatchEvent(new Event('input', { bubbles: true }));
    return new Promise((r) => setTimeout(() => {
      const btn = document.querySelector('button[aria-label="Send"]');
      const disabledBefore = btn.disabled;
      btn.click();
      r(JSON.stringify({ disabledBefore }));
    }, 100));
  })()`);

await send("Page.enable");
await send("Runtime.enable");

// Mobile, dark: overflow + sidebar overlay.
await viewport(375, 812, true);
await go(`${base}/?theme=dark&agent=assistant`);
console.log("mobile 375 overflow", await overflow());
await evaluate(`document.querySelector('button[aria-label="Open navigation"]').click()`);
await sleep(600);
await shot("mobile-sidebar-open");
console.log("mobile overflow with sidebar", await overflow());
await evaluate(`document.querySelector('nav[aria-label="Agents"] button:nth-child(3)').click()`);
await sleep(600);
console.log("after selecting from overlay:", await evaluate(`document.querySelector('main span.block')?.textContent`));
await shot("mobile-after-select");

// Desktop: send flow + running state + reply.
await viewport(1440, 900, false);
await go(`${base}/?theme=dark&agent=market-researcher`);
console.log("send button disabled when empty:", await evaluate(`document.querySelector('button[aria-label="Send"]').disabled`));
console.log("send:", await typeAndSend("Compare Mastra and LangGraph pricing in one table, please."));
await sleep(300);
console.log("running state:", await evaluate(`JSON.stringify({ stop: !!document.querySelector('button[aria-label="Stop"]'), working: document.body.innerText.includes('Working') })`));
await shot("desktop-running");
await sleep(1600);
console.log("after reply:", await evaluate(`JSON.stringify({ stop: !!document.querySelector('button[aria-label="Stop"]'), bubbles: document.querySelectorAll('[data-testid=message-bot-bubble]').length })`));
await shot("desktop-replied");

// Stop flow.
await typeAndSend("Another question");
await sleep(300);
await evaluate(`document.querySelector('button[aria-label="Stop"]').click()`);
await sleep(1500);
console.log("after stop:", await evaluate(`JSON.stringify({ stop: !!document.querySelector('button[aria-label="Stop"]'), bubbles: document.querySelectorAll('[data-testid=message-bot-bubble]').length })`));

// Collapse sidebar.
await evaluate(`document.querySelector('button[aria-label="Hide agents"]').click()`);
await sleep(500);
await shot("desktop-collapsed");
console.log("restore visible:", await evaluate(`!!document.querySelector('button[aria-label="Show agents"]')`));
await evaluate(`document.querySelector('button[aria-label="Show agents"]').click()`);

// Unread: send in one agent, switch away before reply.
await typeAndSend("ping");
await evaluate(`document.querySelector('nav[aria-label="Agents"] button:nth-child(1)').click()`);
await sleep(1800);
console.log("unread dot on market researcher:", await evaluate(`!!document.querySelector('nav[aria-label="Agents"] button:nth-child(2) .sr-only')`));
await shot("desktop-unread");

ws.close();
chrome.kill();

