// Usage: node cdp-s4.mjs <baseUrl> <outDir>
// Drives headless Chromium over CDP against the real agents (S4 verification).
import { spawn } from "node:child_process";
import { writeFileSync } from "node:fs";

const [base, outDir] = process.argv.slice(2);
const shell =
  "/Users/apple/Library/Caches/ms-playwright/chromium_headless_shell-1228/chrome-headless-shell-mac-arm64/chrome-headless-shell";
const port = 9334;
const chrome = spawn(shell, [
  `--remote-debugging-port=${port}`,
  "--user-data-dir=/Users/apple/.claude/jobs/1ad8a391/tmp/chrome-profile-s4",
  "--hide-scrollbars",
  "about:blank",
]);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const log = (...a) => console.log(new Date().toISOString().slice(11, 19), ...a);

async function target() {
  for (let i = 0; i < 50; i++) {
    try {
      const list = await (await fetch(`http://127.0.0.1:${port}/json`)).json();
      const page = list.find((t) => t.type === "page");
      if (page) return page.webSocketDebuggerUrl;
    } catch {}
    await sleep(200);
  }
  throw new Error("no CDP target");
}

const ws = new WebSocket(await target());
await new Promise((r) => ws.addEventListener("open", r));
let seq = 0;
const pending = new Map();
const eventHandlers = [];
ws.addEventListener("message", (event) => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg);
    pending.delete(msg.id);
  } else if (msg.method) {
    for (const handler of eventHandlers) handler(msg);
  }
});
const send = (method, params = {}) =>
  new Promise((resolve) => {
    const id = ++seq;
    pending.set(id, resolve);
    ws.send(JSON.stringify({ id, method, params }));
  });
const evaluate = async (expression) => {
  const res = await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
  if (res.result?.exceptionDetails) return `EXC: ${res.result.exceptionDetails.exception?.description ?? "?"}`;
  return res.result?.result?.value;
};
const shot = async (name) => {
  const { result } = await send("Page.captureScreenshot", { format: "png" });
  writeFileSync(`${outDir}/${name}.png`, Buffer.from(result.data, "base64"));
  log("shot", name);
};
const waitFor = async (expression, timeoutMs, label) => {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    if (await evaluate(expression)) return true;
    await sleep(250);
  }
  log("TIMEOUT waiting for", label);
  return false;
};
const typeAndSend = (text) =>
  evaluate(`(() => {
    const ta = document.querySelector('textarea[name="chat-message"]');
    const setter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set;
    setter.call(ta, ${JSON.stringify(text)});
    ta.dispatchEvent(new Event('input', { bubbles: true }));
    return new Promise((r) => setTimeout(() => { document.querySelector('button[aria-label="Send"]').click(); r(true); }, 100));
  })()`);
const selectAgent = (n) => evaluate(`document.querySelector('nav[aria-label="Agents"] button:nth-child(${n})').click()`);
const running = `!!document.querySelector('button[aria-label="Stop"]')`;
const idle = `!document.querySelector('button[aria-label="Stop"]')`;
const botTexts = `JSON.stringify([...document.querySelectorAll('[data-testid=message-bot-bubble]')].map(e => e.innerText))`;
const lastBotLen = `(() => { const b = [...document.querySelectorAll('[data-testid=message-bot-bubble]')]; return b.length ? b.at(-1).innerText.length : 0; })()`;
const toolRows = `JSON.stringify([...document.querySelectorAll('[data-testid=tool-activity]')].map(e => e.innerText.replace(/\\n+/g, ' | ')))`;

await send("Page.enable");
await send("Runtime.enable");
await send("Network.enable");
await send("Emulation.setDeviceMetricsOverride", { width: 1440, height: 900, deviceScaleFactor: 1, mobile: false });
await send("Page.navigate", { url: `${base}/?theme=dark&agent=assistant` });
await sleep(3000);

// 1. Assistant streamed reply.
log("== assistant: Say hi in 5 words");
await typeAndSend("Say hi in 5 words");
await waitFor(running, 5000, "running");
const sawStreaming = await waitFor(`document.querySelectorAll('[data-testid=message-bot-bubble]').length > 0 && ${running}`, 60000, "streaming text");
log("saw text while still running (streaming):", sawStreaming);
await waitFor(idle, 90000, "assistant done");
const assistantFirst = await evaluate(botTexts);
log("assistant bubbles:", assistantFirst);
await shot("s4-assistant");

// 2. CFO.
log("== cfo");
await selectAgent(3);
await sleep(500);
await typeAndSend("What is the runway with $120k cash and $15k monthly burn? Answer in one line.");
await waitFor(running, 5000, "cfo running");
await waitFor(idle, 120000, "cfo done");
log("cfo bubbles:", await evaluate(botTexts));
log("cfo tools:", await evaluate(toolRows));
await shot("s4-cfo");

// 3. Back to assistant: history retained.
log("== back to assistant");
await selectAgent(1);
await sleep(800);
const assistantAgain = await evaluate(botTexts);
log("history retained:", assistantAgain === assistantFirst, assistantAgain);
log("sidebar previews:", await evaluate(`JSON.stringify([...document.querySelectorAll('nav[aria-label="Agents"] button')].map(b => b.innerText.replace(/\\n+/g, ' | ')))`));
await shot("s4-history");

// 4. Stop mid-stream.
log("== stop mid-stream");
await typeAndSend("Write a detailed 800-word essay on the history of double-entry bookkeeping.");
await waitFor(`${lastBotLen} > 120 && ${running}`, 90000, "essay streaming");
const before = await evaluate(lastBotLen);
await evaluate(`document.querySelector('button[aria-label="Stop"]').click()`);
await waitFor(idle, 5000, "stopped");
await sleep(2000);
const after = await evaluate(lastBotLen);
log("stopped: length at stop", before, "2s later", after, "running?", await evaluate(running));
await shot("s4-stopped");

// 5. Market researcher tool call.
log("== market researcher tool call");
await selectAgent(2);
await sleep(500);
await typeAndSend("Look up Stripe's headcount");
const liveTool = await waitFor(`!!document.querySelector('[data-testid=tool-activity][data-live]')`, 60000, "live tool card");
if (liveTool) {
  log("live tool card:", await evaluate(toolRows));
  await shot("s4-tool-live");
}
await waitFor(idle, 180000, "researcher done");
log("tool cards after:", await evaluate(toolRows));
log("researcher bubble chars:", await evaluate(lastBotLen));
await evaluate(`document.querySelectorAll('[data-testid=tool-activity]').forEach(d => d.open = true)`);
await shot("s4-tool-done");

// 6a. Error: server answers 404 (unknown agent) via request interception.
log("== error: 404 from chat route");
await selectAgent(3);
await sleep(500);
await send("Fetch.enable", { patterns: [{ urlPattern: "*/api/chat/*", requestStage: "Request" }] });
let intercepted = 0;
eventHandlers.push((msg) => {
  if (msg.method !== "Fetch.requestPaused") return;
  intercepted += 1;
  send("Fetch.fulfillRequest", {
    requestId: msg.params.requestId,
    responseCode: 404,
    responseHeaders: [{ name: "content-type", value: "application/json" }],
    body: Buffer.from(JSON.stringify({ error: "Unknown agent: cfoAgent" })).toString("base64"),
  });
});
await typeAndSend("This request will be rejected");
await waitFor(`!!document.querySelector('[data-testid=message-error]')`, 15000, "error bubble");
log("intercepted:", intercepted, "error text:", await evaluate(`document.querySelector('[data-testid=message-error]')?.innerText`));
await shot("s4-error");

// 6b. Retry with the server reachable again.
await send("Fetch.disable");
eventHandlers.length = 0;
await evaluate(`[...document.querySelectorAll('[data-testid=message-error] button')].find(b => b.innerText.includes('Retry')).click()`);
await waitFor(`!document.querySelector('[data-testid=message-error]')`, 5000, "error cleared");
await waitFor(running, 5000, "retry running");
await waitFor(idle, 120000, "retry done");
log("after retry error shown?", await evaluate(`!!document.querySelector('[data-testid=message-error]')`), "bubbles:", await evaluate(botTexts));
await shot("s4-retry");

// 6c. Network down (server unreachable).
log("== error: offline");
await send("Network.emulateNetworkConditions", { offline: true, latency: 0, downloadThroughput: -1, uploadThroughput: -1 });
await typeAndSend("Offline test");
await waitFor(`!!document.querySelector('[data-testid=message-error]')`, 15000, "offline error");
log("offline error text:", await evaluate(`document.querySelector('[data-testid=message-error]')?.innerText`));
await shot("s4-offline");
await send("Network.emulateNetworkConditions", { offline: false, latency: 0, downloadThroughput: -1, uploadThroughput: -1 });

// 7. Mobile view of the assistant conversation.
await send("Emulation.setDeviceMetricsOverride", { width: 390, height: 844, deviceScaleFactor: 1, mobile: true });
await selectAgent(2);
await sleep(800);
log("mobile overflow:", await evaluate(`JSON.stringify({ scrollW: document.documentElement.scrollWidth, innerW: innerWidth })`));
await shot("s4-mobile");

ws.close();
chrome.kill();

