// Measures the NEW tool results by calling the real tool code. Usage:
//   npx tsx --env-file=/Users/apple/Open/nlhack/.env crust-after.mts <toolsFile> <which...>
// which: enrich | enrich-extras | search | web
const [toolsFile, ...which] = process.argv.slice(2);
const tools = await import(toolsFile);

const size = (v: unknown) => {
  const bytes = Buffer.byteLength(JSON.stringify(v) ?? "", "utf8");
  return `${bytes} B (~${Math.round(bytes / 4)} tok)`;
};
const run = (tool: any, input: unknown) => tool.execute(input, {});

if (which.includes("enrich-extras")) {
  const r = await run(tools.crustdataCompanyEnrich, { domain: "zeptonow.com", extras: ["people", "news"] });
  console.log("NEW enrich (people+news):", size(r));
  const c = r.results?.[0] ?? r;
  for (const [k, v] of Object.entries(c)) console.log("  section", k, size(v));
  console.log("  people sample:", JSON.stringify(c.people?.founders?.slice?.(0, 2)).slice(0, 400));
  console.log("  people counts:", c.people && Object.fromEntries(Object.entries(c.people).map(([k, v]) => [k, Array.isArray(v) ? v.length : v])));
  console.log("  news count:", Array.isArray(c.news) ? c.news.length : c.news, JSON.stringify(c.news?.[0] ?? null).slice(0, 300));
  console.log("  funding:", JSON.stringify(c.funding).slice(0, 400));
}
if (which.includes("enrich")) {
  const r = await run(tools.crustdataCompanyEnrich, { domain: "zeptonow.com", extras: [] });
  console.log("NEW enrich (core):", size(r));
  console.log(JSON.stringify(r).slice(0, 1500));
}
if (which.includes("search")) {
  const r = await run(tools.crustdataCompanySearch, { query: "quick commerce grocery delivery India", limit: 5 });
  console.log("NEW search:", size(r), "rows:", r.companies?.length);
}
if (which.includes("web")) {
  const r = await run(tools.crustdataWebSearch, { query: "Zepto quick commerce news", sources: ["web", "news"] });
  console.log("NEW web:", size(r), "rows:", r.results?.length);
}

